// One-off seed: populates SareeStory rows from the saree heritage document
// the user supplied. Run with: node scripts/seed-saree-stories.mjs
// Safe to re-run — it upserts by slugified name (skips ones that already exist).
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_-]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function inferFabric(name) {
  const n = name.toLowerCase();
  if (n.includes("silk")) return "Silk";
  if (n.includes("cotton")) return "Cotton";
  if (n.includes("linen")) return "Linen";
  if (n.includes("organza")) return "Organza";
  if (n.includes("crepe")) return "Crepe";
  if (n.includes("georgette")) return "Georgette";
  if (n.includes("jute")) return "Jute";
  return null;
}

export const STORIES = [];

function add(entry) {
  STORIES.push({
    fabric: inferFabric(entry.name),
    origin: entry.region ? `Traditionally woven in ${entry.region}.` : null,
    interestingFacts: entry.yearsFact ? [entry.yearsFact] : [],
    shortIntro: (entry.history || entry.traditionalUsage || "").split(/(?<=[.!?])\s+/).slice(0, 2).join(" ").slice(0, 590),
    isPublished: true,
    sortOrder: STORIES.length,
    ...entry,
  });
}

