console.log("All entries loaded:", STORIES.length);

async function run() {
  let created = 0, skipped = 0;
  for (const entry of STORIES) {
    const { name, region, fabric, origin, history, traditionalUsage, interestingFacts, shortIntro, isPublished, sortOrder } = entry;

    let slug = slugify(name);
    let n = 1;
    // eslint-disable-next-line no-await-in-loop
    while (await db.sareeStory.findUnique({ where: { slug } })) slug = `${slugify(name)}-${++n}`;

    const existingByName = await db.sareeStory.findFirst({ where: { name } });
    if (existingByName) { skipped++; continue; }

    await db.sareeStory.create({
      data: { name, slug, region, fabric, origin, history, traditionalUsage, interestingFacts, shortIntro, isPublished, sortOrder },
    });
    created++;
  }
  console.log(`Done. Created: ${created}, skipped (already existed): ${skipped}`);
  await db.$disconnect();
}

run().catch(async (e) => {
  console.error(e);
  await db.$disconnect();
  process.exit(1);
});
